    for (int i = 0; i < nnz; i++) {
        indices[i] = (i * 17) % N;
        data[i] = (i % 7) * 0.1 - 0.3;
    }
    for (int i = 0; i < N; i++) x[i] = 1.0;

    // warmup
    for (int rep = 0; rep < 100; rep++) {
        for (int i = 0; i < N; i++) {
            double s = 0.0;
            int a = indptr[i], b = indptr[i+1];
            for (int j = a; j < b; j++) s += data[j] * x[indices[j]];
            y[i] = s;
        }
    }
    int reps = 20000;
    double t0 = now();
    for (int rep = 0; rep < reps; rep++) {
        for (int i = 0; i < N; i++) {
            double s = 0.0;
            int a = indptr[i], b = indptr[i+1];
            for (int j = a; j < b; j++) s += data[j] * x[indices[j]];
            y[i] = s;
        }
        x[0] += y[0] * 1e-18; // prevent optimize-out
    }
    double dt = now() - t0;
    printf("C matvec %.3f us  checksum %f\n", dt/reps*1e6, y[0]+x[0]);
    return 0;
}
