} arnaud_state;

extern void ARNAUD_dnaupd(arnaud_state *state, double *resid, double *v,
                           int32_t *ipntr, double *workd, double *workl,
                           int32_t *lworkl);
extern void ARNAUD_dneupd(arnaud_state *state, int32_t rvec, int32_t howmny,
                           int32_t *select, double *dr, double *di, double *z,
                           double sigmar, double sigmai, double *workev,
                           double *resid, double *v, int32_t *ipntr,
                           double *workd, double *workl, int32_t *lworkl);

static void matvec(const int32_t *indptr, const int32_t *indices,
                   const double *data, const double *x, double *y, int n) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int a = indptr[i];
        int b = indptr[i + 1];
        for (int j = a; j < b; j++) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

/* argv: n k ncv maxiter indptr_file?  We'll read everything from stdin binary:
   int32 n, k, ncv, maxiter
   int32 indptr[n+1]
   int32 indices[nnz]
   double data[nnz]
   writes: int32 info, nconv
   double dr[k+1], di[k+1]
   double zr[(k+1)*n] column major
*/
int main(void) {
    int32_t n, k, ncv, maxiter;
    if (fread(&n, 4, 1, stdin) != 1) return 2;
    fread(&k, 4, 1, stdin);
    fread(&ncv, 4, 1, stdin);
    fread(&maxiter, 4, 1, stdin);
    int32_t *indptr = malloc((n + 1) * 4);
    fread(indptr, 4, n + 1, stdin);
    int32_t nnz = indptr[n];
    int32_t *indices = malloc(nnz * 4);
    double *data = malloc(nnz * 8);
    fread(indices, 4, nnz, stdin);
    fread(data, 8, nnz, stdin);

    double *resid = malloc(n * 8);
    for (int i = 0; i < n; i++) resid[i] = 1.0;
    double *v = calloc((size_t)n * ncv, 8);
    double *workd = calloc(3 * n, 8);
    int32_t lworkl = 3 * ncv * (ncv + 2);
    double *workl = calloc(lworkl, 8);
    int32_t ipntr[14] = {0};

    arnaud_state st;
    memset(&st, 0, sizeof(st));
    st.which = 0; /* LM */
    st.ido = 0;
    st.info = 1;  /* use resid */
    st.bmat = 0;  /* identity */
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;
    st.tol = 0.0;

    int guard = 0;
    for (;;) {
        ARNAUD_dnaupd(&st, resid, v, ipntr, workd, workl, &lworkl);
        int ido = st.ido;
        if (ido == 1 || ido == 5) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            matvec(indptr, indices, data, workd + x0, workd + y0, n);
        } else if (ido == 2) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            memcpy(workd + y0, workd + x0, n * 8);
        } else if (ido == 4) {
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
        if (++guard > 10000000) { st.info = -999; break; }
    }
    int32_t info = st.info;
    int32_t nconv = st.nconv;

    double *dr = calloc(k + 1, 8);
    double *di = calloc(k + 1, 8);
    double *zr = calloc((size_t)(k + 1) * n, 8);
    double *workev = calloc(3 * ncv, 8);
    int32_t *sel = calloc(ncv, 4);
    int32_t exinfo = 0;
    if (info == 0) {
        st.info = 0;
        ARNAUD_dneupd(&st, 1, 0, sel, dr, di, zr, 0.0, 0.0, workev,
                      resid, v, ipntr, workd, workl, &lworkl);
        exinfo = st.info;
        nconv = st.nconv;
    }
    fwrite(&info, 4, 1, stdout);
    fwrite(&exinfo, 4, 1, stdout);
    fwrite(&nconv, 4, 1, stdout);
    fwrite(&st.iter, 4, 1, stdout);
    fwrite(dr, 8, k + 1, stdout);
    fwrite(di, 8, k + 1, stdout);
    fwrite(zr, 8, (size_t)(k + 1) * n, stdout);
    return 0;
}
