#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

static inline double dabs(double x) { return x < 0 ? -x : x; }

static void house3(double x, double y, double z, double *v1, double *v2, double *beta) {
    double nrm = sqrt(x*x + y*y + z*z);
    if (nrm == 0.0) { *v1 = 0; *v2 = 0; *beta = 0; return; }
    double v0 = (x >= 0.0) ? x + nrm : x - nrm;
    double inv = 1.0 / v0;
    *v1 = y * inv;
    *v2 = z * inv;
    *beta = 2.0 / (1.0 + (*v1)*(*v1) + (*v2)*(*v2));
}

static void house2(double x, double y, double *v1, double *beta) {
    double nrm = sqrt(x*x + y*y);
    if (nrm == 0.0) { *v1 = 0; *beta = 0; return; }
    double v0 = (x >= 0.0) ? x + nrm : x - nrm;
    *v1 = y / v0;
    *beta = 2.0 / (1.0 + (*v1)*(*v1));
}

/* H, wr, wi length n. Returns 0 on success. */
int eigvals_real(const double *A, int n, double *wr, double *wi) {
    double *H = (double *)malloc((size_t)n * n * sizeof(double));
    if (!H) return -1;
    memcpy(H, A, (size_t)n * n * sizeof(double));
    #define H(i,j) H[(i)*n + (j)]

    for (int k = 0; k < n - 2; k++) {
        double ss = 0.0;
        for (int i = k + 1; i < n; i++) ss += H(i,k) * H(i,k);
        double normx = sqrt(ss);
        if (normx == 0.0) continue;
        double x0 = H(k+1, k);
        double v0, sub;
        if (x0 >= 0.0) { v0 = x0 + normx; sub = -normx; }
        else { v0 = x0 - normx; sub = normx; }
        double inv = 1.0 / v0;
        ss = 1.0;
        for (int i = k + 2; i < n; i++) {
            H(i,k) *= inv;
            ss += H(i,k) * H(i,k);
        }
        H(k+1, k) = 1.0;
        double tau = 2.0 / ss;
        for (int j = k + 1; j < n; j++) {
            double s = H(k+1, j);
            for (int i = k + 2; i < n; i++) s += H(i,k) * H(i,j);
            s *= tau;
            H(k+1, j) -= s;
            for (int i = k + 2; i < n; i++) H(i,j) -= s * H(i,k);
        }
        for (int i = 0; i < n; i++) {
            double s = H(i, k+1);
            for (int j = k + 2; j < n; j++) s += H(i,j) * H(j,k);
            s *= tau;
            H(i, k+1) -= s;
            for (int j = k + 2; j < n; j++) H(i,j) -= s * H(j,k);
        }
        H(k+1, k) = sub;
        for (int i = k + 2; i < n; i++) H(i,k) = 0.0;
    }

    const double eps = 2.220446049250313e-16;
    int en = n - 1;
    int fail = 0;
    while (en >= 0) {
        int its = 0;
        for (;;) {
            int l = en;
            while (l > 0) {
                double sabs = dabs(H(l-1,l-1)) + dabs(H(l,l));
                if (dabs(H(l, l-1)) <= eps * sabs) {
                    H(l, l-1) = 0.0;
                    break;
                }
                l--;
            }
            if (l == en) {
                wr[en] = H(en, en);
                wi[en] = 0.0;
                en--;
                break;
            }
            if (l + 1 == en) {
                double a = H(en-1, en-1), b = H(en-1, en), c = H(en, en-1), d = H(en, en);
                double tr = a + d;
                double det = a*d - b*c;
                double disc = tr*tr*0.25 - det;
                if (disc >= 0.0) {
                    double sd = sqrt(disc);
                    double r1 = (tr >= 0.0) ? tr*0.5 + sd : tr*0.5 - sd;
                    double r2 = (r1 != 0.0) ? det / r1 : 0.0;
                    wr[en-1] = r1; wi[en-1] = 0.0;
                    wr[en] = r2; wi[en] = 0.0;
                } else {
                    wr[en-1] = tr*0.5;
                    wi[en-1] = sqrt(-disc);
                    wr[en] = wr[en-1];
                    wi[en] = -wi[en-1];
                }
                en -= 2;
                break;
            }
            its++;
            if (its > 100) { fail = 1; en = l - 1; break; }
            double ss, tt;
            if (its == 10 || its == 20 || its == 30 || its == 40 || its == 50) {
                double exs = H(en, en) + dabs(H(en, en-1));
                ss = 2.0 * exs;
                tt = exs * exs;
            } else {
                ss = H(en-1, en-1) + H(en, en);
                tt = H(en-1, en-1)*H(en, en) - H(en-1, en)*H(en, en-1);
            }
            double h00 = H(l, l), h01 = H(l, l+1), h10 = H(l+1, l);
            double h11 = H(l+1, l+1), h21 = H(l+2, l+1);
            double x = h00*h00 + h01*h10 - ss*h00 + tt;
            double y = h10 * (h00 + h11 - ss);
            double z = h10 * h21;
            for (int k = l; k <= en - 2; k++) {
                double v1, v2, beta;
                house3(x, y, z, &v1, &v2, &beta);
                if (beta != 0.0) {
                    int q = (k == l) ? k : k - 1;
                    for (int j = q; j <= en; j++) {
                        double sdot = H(k,j) + v1*H(k+1,j) + v2*H(k+2,j);
                        sdot *= beta;
                        H(k,j) -= sdot;
                        H(k+1,j) -= sdot * v1;
                        H(k+2,j) -= sdot * v2;
                    }
                    int rlim = k + 3;
                    if (rlim > en) rlim = en;
                    for (int i = l; i <= rlim; i++) {
                        double sdot = H(i,k) + v1*H(i,k+1) + v2*H(i,k+2);
                        sdot *= beta;
                        H(i,k) -= sdot;
                        H(i,k+1) -= sdot * v1;
                        H(i,k+2) -= sdot * v2;
                    }
                }
                x = H(k+1, k);
                y = H(k+2, k);
                z = (k < en - 2) ? H(k+3, k) : 0.0;
            }
            {
                double v1, beta;
                house2(x, y, &v1, &beta);
                if (beta != 0.0) {
                    int q = en - 3;
                    if (q < l) q = l;
                    for (int j = q; j <= en; j++) {
                        double sdot = H(en-1, j) + v1*H(en, j);
                        sdot *= beta;
                        H(en-1, j) -= sdot;
                        H(en, j) -= sdot * v1;
                    }
                    for (int i = l; i <= en; i++) {
                        double sdot = H(i, en-1) + v1*H(i, en);
                        sdot *= beta;
                        H(i, en-1) -= sdot;
                        H(i, en) -= sdot * v1;
                    }
                }
            }
        }
    }
    free(H);
    return fail;
}

int main() {
    int n = 200;
    double *A = malloc((size_t)n*n*sizeof(double));
    double *wr = malloc(n*sizeof(double));
    double *wi = malloc(n*sizeof(double));
    srand(1);
    for (int i = 0; i < n*n; i++) A[i] = ((rand() % 10000) - 5000) / 5000.0;
    /* warmup */
    eigvals_real(A, n, wr, wi);
    clock_t t0; /* use clock? better gettime */
    /* use a simple loop count via clock from time.h */
    #include <time.h>
    struct timespec ts0, ts1;
    clock_gettime(CLOCK_MONOTONIC, &ts0);
    int reps = 3;
    for (int r = 0; r < reps; r++) eigvals_real(A, n, wr, wi);
    clock_gettime(CLOCK_MONOTONIC, &ts1);
    double ms = (ts1.tv_sec - ts0.tv_sec)*1000.0 + (ts1.tv_nsec - ts0.tv_nsec)/1e6;
    printf("ms/rep %.2f sample %g %g\n", ms/reps, wr[0], wi[0]);
    free(A); free(wr); free(wi);
    return 0;
}
