    *beta = 2.0 / (1.0 + (*v1)*(*v1));
}

int eigvals_real(const double *A, int n, double *wr, double *wi) {
    double *H = (double *)malloc((size_t)n * n * sizeof(double));
    if (!H) return -1;
    memcpy(H, A, (size_t)n * n * sizeof(double));
    #define H(i,j) H[(size_t)(i)*n + (j)]

    double *vstore = (double *)malloc((size_t)n * sizeof(double));
    for (int k = 0; k < n - 2; k++) {
        double ss = 0.0;
        for (int i = k + 1; i < n; i++) ss += H(i,k) * H(i,k);
        double normx = sqrt(ss);
        if (normx == 0.0) continue;
        double x0 = H(k+1, k);
        double v0, sub;
        if (x0 >= 0.0) { v0 = x0 + normx; sub = -normx; }
        else { v0 = x0 - normx; sub = normx; }
        double inv = 1.0 / v0;
        ss = 1.0;
        vstore[k+1] = 1.0;
        for (int i = k + 2; i < n; i++) {
            vstore[i] = H(i,k) * inv;
            ss += vstore[i] * vstore[i];
        }
        double tau = 2.0 / ss;
        #pragma omp parallel for schedule(static)
        for (int j = k + 1; j < n; j++) {
            double s = H(k+1, j);
            for (int i = k + 2; i < n; i++) s += vstore[i] * H(i,j);
            s *= tau;
            H(k+1, j) -= s;
            for (int i = k + 2; i < n; i++) H(i,j) -= s * vstore[i];
        }
        #pragma omp parallel for schedule(static)
        for (int i = 0; i < n; i++) {
            double s = H(i, k+1);
