            s *= tau;
            H(i, k+1) -= s;
            for (int j = k + 2; j < n; j++) H(i,j) -= s * vstore[j];
        }
        H(k+1, k) = sub;
        for (int i = k + 2; i < n; i++) H(i,k) = 0.0;
    }
    free(vstore);

    const double eps = 2.220446049250313e-16;
    int en = n - 1;
    int fail = 0;
    while (en >= 0) {
        int its = 0;
        for (;;) {
            int l = en;
            while (l > 0) {
                double sabs = dabs(H(l-1,l-1)) + dabs(H(l,l));
                if (dabs(H(l, l-1)) <= eps * sabs) { H(l, l-1) = 0.0; break; }
                l--;
            }
            if (l == en) { wr[en] = H(en,en); wi[en] = 0.0; en--; break; }
            if (l + 1 == en) {
                double a = H(en-1,en-1), b = H(en-1,en), c = H(en,en-1), d = H(en,en);
                double tr = a + d, det = a*d - b*c, disc = tr*tr*0.25 - det;
                if (disc >= 0.0) {
                    double sd = sqrt(disc);
                    double r1 = (tr >= 0.0) ? tr*0.5 + sd : tr*0.5 - sd;
                    double r2 = (r1 != 0.0) ? det / r1 : 0.0;
                    wr[en-1] = r1; wi[en-1] = 0.0; wr[en] = r2; wi[en] = 0.0;
                } else {
                    wr[en-1] = tr*0.5; wi[en-1] = sqrt(-disc);
                    wr[en] = wr[en-1]; wi[en] = -wi[en-1];
                }
                en -= 2; break;
            }
            its++;
            if (its > 100) { fail = 1; en = l - 1; break; }
            double ss, tt;
            if (its % 10 == 0) {
                double exs = H(en,en) + dabs(H(en,en-1));
                ss = 2.0 * exs; tt = exs * exs;
            } else {
                ss = H(en-1,en-1) + H(en,en);
                tt = H(en-1,en-1)*H(en,en) - H(en-1,en)*H(en,en-1);
            }
            double h00 = H(l,l), h01 = H(l,l+1), h10 = H(l+1,l);
            double h11 = H(l+1,l+1), h21 = H(l+2,l+1);
            double x = h00*h00 + h01*h10 - ss*h00 + tt;
            double y = h10 * (h00 + h11 - ss);
            double z = h10 * h21;
            for (int k = l; k <= en - 2; k++) {
                double v1, v2, beta;
                house3(x, y, z, &v1, &v2, &beta);
                if (beta != 0.0) {
                    int q = (k == l) ? k : k - 1;
                    int rlim = k + 3; if (rlim > en) rlim = en;
                    int j;
                    #pragma omp parallel for schedule(static)
                    for (j = q; j <= en; j++) {
                        double sdot = H(k,j) + v1*H(k+1,j) + v2*H(k+2,j);
                        sdot *= beta;
                        H(k,j) -= sdot;
                        H(k+1,j) -= sdot * v1;
                        H(k+2,j) -= sdot * v2;
                    }
                    int i;
                    #pragma omp parallel for schedule(static)
                    for (i = l; i <= rlim; i++) {
                        double sdot = H(i,k) + v1*H(i,k+1) + v2*H(i,k+2);
                        sdot *= beta;
                        H(i,k) -= sdot;
                        H(i,k+1) -= sdot * v1;
                        H(i,k+2) -= sdot * v2;
                    }
                }
                x = H(k+1,k);
                y = H(k+2,k);
                z = (k < en - 2) ? H(k+3,k) : 0.0;
            }
            {
                double v1, beta;
                house2(x, y, &v1, &beta);
