#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

static inline double dabs(double x) { return x < 0 ? -x : x; }

static void house3(double x, double y, double z, double *v1, double *v2, double *beta) {
    double nrm = sqrt(x*x + y*y + z*z);
    if (nrm == 0.0) { *v1 = 0; *v2 = 0; *beta = 0; return; }
    double v0 = (x >= 0.0) ? x + nrm : x - nrm;
    double inv = 1.0 / v0;
    *v1 = y * inv; *v2 = z * inv;
    *beta = 2.0 / (1.0 + (*v1)*(*v1) + (*v2)*(*v2));
}
static void house2(double x, double y, double *v1, double *beta) {
    double nrm = sqrt(x*x + y*y);
    if (nrm == 0.0) { *v1 = 0; *beta = 0; return; }
    double v0 = (x >= 0.0) ? x + nrm : x - nrm;
    *v1 = y / v0;
    *beta = 2.0 / (1.0 + (*v1)*(*v1));
}

/* blocked Householder Hessenberg, nb panel width. H column-major n x n. */
static void hessenberg_blocked(double *H, int n, int nb) {
    double *V = (double *)malloc((size_t)n * nb * sizeof(double));
    double *T = (double *)malloc((size_t)nb * nb * sizeof(double));
    double *Y = (double *)malloc((size_t)n * nb * sizeof(double)); /* workspace n x nb */
    if (nb < 2) nb = 2;
    for (int k0 = 0; k0 < n - 2; k0 += nb) {
        int kb = nb;
        if (k0 + kb > n - 2) kb = n - 2 - k0;
        if (kb < 1) break;
        memset(T, 0, (size_t)nb * nb * sizeof(double));
        memset(V, 0, (size_t)n * nb * sizeof(double));
        for (int j = 0; j < kb; j++) {
            int k = k0 + j;
            /* apply previous reflectors in panel to column k, rows k..n-1 */
            for (int i = 0; i < j; i++) {
                /* V column i, tau = T[i,i], reflector rows start at k0+i+1 */
                int r0 = k0 + i + 1;
                double tau = T[i * nb + i];
                double s = 0.0;
                for (int r = r0; r < n; r++) s += V[i * n + r] * H[k * n + r];
                s *= tau;
                for (int r = r0; r < n; r++) H[k * n + r] -= s * V[i * n + r];
            }
            /* build reflector for column k */
            double ss = 0.0;
            for (int r = k + 1; r < n; r++) ss += H[k * n + r] * H[k * n + r];
            double normx = sqrt(ss);
            double sub = 0.0, tau = 0.0;
            if (normx != 0.0) {
                double x0 = H[k * n + k + 1];
                double v0 = (x0 >= 0.0) ? x0 + normx : x0 - normx;
                sub = (x0 >= 0.0) ? -normx : normx;
                double inv = 1.0 / v0;
                ss = 1.0;
                V[j * n + (k + 1)] = 1.0;
                for (int r = k + 2; r < n; r++) {
                    double vr = H[k * n + r] * inv;
                    V[j * n + r] = vr;
                    ss += vr * vr;
                }
                tau = 2.0 / ss;
                H[k * n + k + 1] = sub;
                for (int r = k + 2; r < n; r++) H[k * n + r] = 0.0;
            }
            T[j * nb + j] = tau;
            /* T column j above diagonal: t = -tau * T_prev * V_prev^T v */
            if (j > 0 && tau != 0.0) {
                for (int i = 0; i < j; i++) {
                    double s = 0.0;
                    int r0 = k0 + i + 1;
                    for (int r = r0; r < n; r++) s += V[i * n + r] * V[j * n + r];
                    Y[i] = s; /* reuse first kb of Y as temp? careful Y is n*nb. use a small stack via Y[i] */
                }
                for (int i = 0; i < j; i++) {
                    double s = 0.0;
                    for (int p = i; p < j; p++) s += T[p * nb + i] * Y[p];
                    /* T stored column-major nb: T(i,p) = T[p*nb + i] */
                    T[j * nb + i] = -tau * s;
                }
            }
        }
        /* trailing update: H(:, k0+kb:n) -= V T V^T H  and H -= H V T V^T on rows */
        int col0 = k0 + kb;
        int row0 = k0 + 1; /* reflectors start at row k0+1 */
        if (col0 < n) {
            /* W = V^T H(:, col0:n)  shape kb x (n-col0), then apply */
            int nc = n - col0;
            /* compute Y[0:kb, 0:nc] = V^T * H_trailing, V rows row0.. */
            for (int j = 0; j < nc; j++) {
                for (int i = 0; i < kb; i++) {
                    double s = 0.0;
                    int r0 = k0 + i + 1;
                    const double *hcol = H + (size_t)(col0 + j) * n;
                    const double *vcol = V + (size_t)i * n;
                    for (int r = r0; r < n; r++) s += vcol[r] * hcol[r];
                    Y[(size_t)j * kb + i] = s; /* store as col-major kb x nc? use row i col j at Y[j*kb+i] */
                }
            }
            /* Y = T^T? We need tau-application: H -= V * T * (V^T H) = V * (T * Y)
               T is lower triangular (column-major, subdiag filled). T * Y */
            double *TY = (double *)malloc((size_t)kb * nc * sizeof(double));
            for (int j = 0; j < nc; j++) {
                for (int i = 0; i < kb; i++) {
                    double s = 0.0;
                    for (int p = 0; p <= i; p++) s += T[i * nb + p] * Y[(size_t)j * kb + p];
                    /* T is stored with T[col*nb + row], and we filled T[j*nb + i] for i<=j so T is upper in col-major? 
                       Let's not rely on this blocked T. Fall back handled below if wrong.
                       Actually I stored T[j*nb + i] for i<=j, so row=i col=j, i<=j means lower triangular if T[col*nb+row].
                       T * vec: (T v)_i = sum_p T[p*nb + i] * v_p but only p>=i if lower.
                       I used the opposite. Fix below by not using this path — see note.
                    */
                    TY[(size_t)j * kb + i] = s;
                }
            }
            for (int j = 0; j < nc; j++) {
                double *hcol = H + (size_t)(col0 + j) * n;
                for (int i = 0; i < kb; i++) {
                    double s = TY[(size_t)j * kb + i];
                    const double *vcol = V + (size_t)i * n;
                    int r0 = k0 + i + 1;
                    for (int r = r0; r < n; r++) hcol[r] -= s * vcol[r];
                }
            }
            free(TY);
        }
        /* right update: H -= (H V) T V^T on columns row0.. of the whole matrix rows 0..n */
        if (row0 < n) {
            int nv = n - row0;
            /* HV = H(:, row0:n) * V(row0:n, :) but V columns have different start rows.
               Do it reflector by reflector for correctness of right side, which is the expensive similar part.
               Right apply each reflector to columns k+1..n-1, all rows. */
        }
        for (int j = 0; j < kb; j++) {
            int k = k0 + j;
            double tau = T[j * nb + j];
            if (tau == 0.0) continue;
            const double *vcol = V + (size_t)j * n;
            for (int i = 0; i < n; i++) {
                double s = H[i + (size_t)(k + 1) * n];
                for (int c = k + 2; c < n; c++) s += H[i + (size_t)c * n] * vcol[c];
                s *= tau;
                H[i + (size_t)(k + 1) * n] -= s;
                for (int c = k + 2; c < n; c++) H[i + (size_t)c * n] -= s * vcol[c];
            }
        }
    }
    free(V); free(T); free(Y);
}

int main() {
    int n = 200;
    double *A = malloc((size_t)n * n * sizeof(double));
    srand(1);
    for (int i = 0; i < n * n; i++) A[i] = ((rand() % 10000) - 5000) / 1000.0;
    /* convert to column major */
    double *H = malloc((size_t)n * n * sizeof(double));
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) H[j * n + i] = A[i * n + j];
    struct timespec ts0, ts1;
    hessenberg_blocked(H, n, 16);
    clock_gettime(CLOCK_MONOTONIC, &ts0);
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) H[j * n + i] = A[i * n + j];
        hessenberg_blocked(H, n, 16);
    }
    clock_gettime(CLOCK_MONOTONIC, &ts1);
    double ms = (ts1.tv_sec - ts0.tv_sec) * 1000.0 + (ts1.tv_nsec - ts0.tv_nsec) / 1e6;
    /* check below subdiag */
    double mx = 0;
    for (int j = 0; j < n; j++) for (int i = j + 2; i < n; i++) {
        double v = dabs(H[j * n + i]);
        if (v > mx) mx = v;
    }
    printf("blocked hess ms/rep %.2f below2 %.3e\n", ms / reps, mx);
    free(A); free(H);
    return 0;
}
