#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>

/* One Hyman-Newton step for each (zr,zi) on upper Hessenberg H (row-major). */
void refine(const double *H, const double *sub, const double *zr, const double *zi,
            double *outr, double *outi, int n) {
    double *xr = malloc(n * sizeof(double));
    double *xi = malloc(n * sizeof(double));
    double *dxr = malloc(n * sizeof(double));
    double *dxi = malloc(n * sizeof(double));
    for (int idx = 0; idx < n; idx++) {
        double zzr = zr[idx], zzi = zi[idx];
        xr[n-1] = 1.0; xi[n-1] = 0.0;
        dxr[n-1] = 0.0; dxi[n-1] = 0.0;
        for (int k = n - 2; k >= 0; k--) {
            double hr = H[(k+1)*n + (k+1)] - zzr;
            double hi = -zzi;
            double sr = hr * xr[k+1] - hi * xi[k+1];
            double si = hr * xi[k+1] + hi * xr[k+1];
            double dsr = hr * dxr[k+1] - hi * dxi[k+1] - xr[k+1];
            double dsi = hr * dxi[k+1] + hi * dxr[k+1] - xi[k+1];
            const double *row = H + (k+1)*n;
            for (int j = k + 2; j < n; j++) {
                double hij = row[j];
                sr += hij * xr[j];
                si += hij * xi[j];
                dsr += hij * dxr[j];
                dsi += hij * dxi[j];
            }
            double inv = 1.0 / sub[k];
            xr[k] = -sr * inv;
            xi[k] = -si * inv;
            dxr[k] = -dsr * inv;
            dxi[k] = -dsi * inv;
        }
        double hr = H[0] - zzr;
        double hi = -zzi;
        double pr = hr * xr[0] - hi * xi[0];
        double pi = hr * xi[0] + hi * xr[0];
        double dpr = hr * dxr[0] - hi * dxi[0] - xr[0];
        double dpi = hr * dxi[0] + hi * dxr[0] - xi[0];
        const double *row0 = H;
        for (int j = 1; j < n; j++) {
            double hij = row0[j];
            pr += hij * xr[j];
            pi += hij * xi[j];
            dpr += hij * dxr[j];
            dpi += hij * dxi[j];
        }
        double den = dpr * dpr + dpi * dpi;
        if (den == 0.0) {
            outr[idx] = zzr; outi[idx] = zzi;
        } else {
            double nr = pr * dpr + pi * dpi;
            double ni = pi * dpr - pr * dpi;
            outr[idx] = zzr - nr / den;
            outi[idx] = zzi - ni / den;
        }
    }
    free(xr); free(xi); free(dxr); free(dxi);
}

int main() {
    int n = 200;
    double *H = calloc((size_t)n*n, sizeof(double));
    double *sub = malloc((n-1)*sizeof(double));
    double *zr = malloc(n*sizeof(double));
    double *zi = malloc(n*sizeof(double));
    double *or_ = malloc(n*sizeof(double));
    double *oi = malloc(n*sizeof(double));
    srand(1);
    for (int i = 0; i < n; i++) {
        for (int j = i-1; j < n; j++) if (j >= 0) H[i*n+j] = ((rand()%1000)-500)/100.0;
        if (i+1 < n) sub[i] = H[(i+1)*n + i];
        zr[i] = ((rand()%1000)-500)/50.0;
        zi[i] = ((rand()%1000)-500)/50.0;
    }
    refine(H, sub, zr, zi, or_, oi, n);
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    int reps = 5;
    for (int r = 0; r < reps; r++) refine(H, sub, zr, zi, or_, oi, n);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double ms = (t1.tv_sec-t0.tv_sec)*1000.0 + (t1.tv_nsec-t0.tv_nsec)/1e6;
    printf("ms/rep %.2f sample %g\n", ms/reps, or_[0]);
    return 0;
}
