void pack_hessenberg(const double *aF, double *H, double *sub, int n) {
    memset(H, 0, (size_t)n * n * sizeof(double));
    for (int j = 0; j < n; j++) {
        const double *col = aF + (size_t)j * n;
        int imax = j + 1;
