} Job;

static void refine_range(Job *job) {
    const double *H = job->H;
    const double *sub = job->sub;
    int n = job->n;
    double *xr = job->xr, *xi = job->xi, *dxr = job->dxr, *dxi = job->dxi;
    for (int idx = job->begin; idx < job->end; idx++) {
        double zzr = job->zr[idx], zzi = job->zi[idx];
        xr[n - 1] = 1.0; xi[n - 1] = 0.0;
        dxr[n - 1] = 0.0; dxi[n - 1] = 0.0;
        int ok = 1;
        for (int k = n - 2; k >= 0; k--) {
            double hk = sub[k];
            if (hk == 0.0) { ok = 0; break; }
            double hr = H[(k + 1) * n + (k + 1)] - zzr;
            double hi = -zzi;
            double sr = hr * xr[k + 1] - hi * xi[k + 1];
            double si = hr * xi[k + 1] + hi * xr[k + 1];
            double dsr = hr * dxr[k + 1] - hi * dxi[k + 1] - xr[k + 1];
            double dsi = hr * dxi[k + 1] + hi * dxr[k + 1] - xi[k + 1];
            const double *row = H + (k + 1) * n;
            for (int j = k + 2; j < n; j++) {
                double hij = row[j];
                sr += hij * xr[j];
                si += hij * xi[j];
                dsr += hij * dxr[j];
                dsi += hij * dxi[j];
            }
            double inv = 1.0 / hk;
            xr[k] = -sr * inv; xi[k] = -si * inv;
            dxr[k] = -dsr * inv; dxi[k] = -dsi * inv;
        }
        if (!ok) { job->outr[idx] = zzr; job->outi[idx] = zzi; continue; }
        double hr = H[0] - zzr;
        double hi = -zzi;
        double pr = hr * xr[0] - hi * xi[0];
        double pi = hr * xi[0] + hi * xr[0];
        double dpr = hr * dxr[0] - hi * dxi[0] - xr[0];
        double dpi = hr * dxi[0] + hi * dxr[0] - xi[0];
        for (int j = 1; j < n; j++) {
            double hij = H[j];
            pr += hij * xr[j]; pi += hij * xi[j];
            dpr += hij * dxr[j]; dpi += hij * dxi[j];
        }
        double den = dpr * dpr + dpi * dpi;
        if (den == 0.0) {
            job->outr[idx] = zzr; job->outi[idx] = zzi;
        } else {
            double nr = pr * dpr + pi * dpi;
            double ni = pi * dpr - pr * dpi;
            job->outr[idx] = zzr - nr / den;
            job->outi[idx] = zzi - ni / den;
        }
    }
}

static void *thread_main(void *arg) {
    refine_range((Job *)arg);
    return NULL;
}

void hyman_refine(const double *H, const double *sub, const double *zr, const double *zi,
                  double *outr, double *outi, int n) {
    int nthreads = 4;
    if (n < 64) nthreads = 1;
    pthread_t threads[8];
    Job jobs[8];
    if (nthreads > 8) nthreads = 8;
    int chunk = (n + nthreads - 1) / nthreads;
    int launched = 0;
    for (int t = 0; t < nthreads; t++) {
        int begin = t * chunk;
        int end = begin + chunk;
        if (begin >= n) break;
        if (end > n) end = n;
        jobs[t].H = H; jobs[t].sub = sub; jobs[t].zr = zr; jobs[t].zi = zi;
        jobs[t].outr = outr; jobs[t].outi = outi; jobs[t].n = n;
        jobs[t].begin = begin; jobs[t].end = end;
        jobs[t].xr = (double *)malloc((size_t)n * sizeof(double));
        jobs[t].xi = (double *)malloc((size_t)n * sizeof(double));
        jobs[t].dxr = (double *)malloc((size_t)n * sizeof(double));
        jobs[t].dxi = (double *)malloc((size_t)n * sizeof(double));
        if (t == nthreads - 1 || end == n) {
            refine_range(&jobs[t]);
        } else {
            pthread_create(&threads[t], NULL, thread_main, &jobs[t]);
            launched++;
        }
    }
    for (int t = 0; t < launched; t++) pthread_join(threads[t], NULL);
    for (int t = 0; t < nthreads; t++) {
        if (jobs[t].begin >= n) break;
        free(jobs[t].xr); free(jobs[t].xi); free(jobs[t].dxr); free(jobs[t].dxi);
    }
}
