#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

/* Column-major unblocked Hessenberg, but right-apply is the bottleneck.
   Use a small panel: accumulate reflectors and apply the right update as a GEMM-like kernel. */

static void hess(double *H, int n) {
    double *v = (double *)malloc((size_t)n * sizeof(double));
    for (int k = 0; k < n - 2; k++) {
        double ss = 0.0;
        double *col = H + (size_t)k * n;
        for (int i = k + 1; i < n; i++) ss += col[i] * col[i];
        double normx = sqrt(ss);
        if (normx == 0.0) continue;
        double x0 = col[k + 1];
        double v0 = (x0 >= 0.0) ? x0 + normx : x0 - normx;
        double sub = (x0 >= 0.0) ? -normx : normx;
        double inv = 1.0 / v0;
        ss = 1.0;
        v[k + 1] = 1.0;
        for (int i = k + 2; i < n; i++) {
            v[i] = col[i] * inv;
            ss += v[i] * v[i];
        }
        double tau = 2.0 / ss;
        /* left apply to columns k+1..n-1 */
        for (int j = k + 1; j < n; j++) {
            double *cj = H + (size_t)j * n;
            double s = cj[k + 1];
            for (int i = k + 2; i < n; i++) s += v[i] * cj[i];
            s *= tau;
            cj[k + 1] -= s;
            for (int i = k + 2; i < n; i++) cj[i] -= s * v[i];
        }
        /* right apply: for each row, dot with v over columns k+1..n-1 */
        for (int i = 0; i < n; i++) {
            double s = H[i + (size_t)(k + 1) * n];
            for (int j = k + 2; j < n; j++) s += H[i + (size_t)j * n] * v[j];
            s *= tau;
            H[i + (size_t)(k + 1) * n] -= s;
            for (int j = k + 2; j < n; j++) H[i + (size_t)j * n] -= s * v[j];
        }
        col[k + 1] = sub;
        for (int i = k + 2; i < n; i++) col[i] = 0.0;
    }
    free(v);
}

int main() {
    int n = 200;
    double *A = malloc((size_t)n * n * sizeof(double));
    double *H = malloc((size_t)n * n * sizeof(double));
    srand(1);
    for (int i = 0; i < n * n; i++) A[i] = (rand() % 1000) / 100.0;
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        memcpy(H, A, (size_t)n * n * sizeof(double));
        hess(H, n);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double ms = (t1.tv_sec - t0.tv_sec) * 1000.0 + (t1.tv_nsec - t0.tv_nsec) / 1e6;
    printf("hess ms/rep %.2f\n", ms / reps);
    return 0;
}
