void build_tps(const double* y, int n, int d, double eps, double* out) {
    double eps2 = eps*eps;
    for (int i = 0; i < n; i++) {
        const double* yi = y + i*d;
        for (int j = 0; j <= i; j++) {
            const double* yj = y + j*d;
            double s = 0.0;
            for (int k = 0; k < d; k++) {
                double diff = yi[k] - yj[k];
                s += diff*diff;
            }
            double r2 = s * eps2;
            double v = 0.0;
            if (r2 > 0.0) {
                double r = sqrt(r2);
                v = r2 * log(r);
            }
            out[i*n + j] = v;
            out[j*n + i] = v;
        }
    }
}

