#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <Accelerate/Accelerate.h>
#include <mach/mach_time.h>

static double now() {
    static mach_timebase_info_data_t info;
    if (info.denom == 0) mach_timebase_info(&info);
    return (double)mach_absolute_time() * info.numer / info.denom / 1e9;
}

typedef struct {
    const double* y;
    double* out;
    int n, d, i0, i1;
    double eps2;
} Job;

void* worker(void* arg) {
    Job* j = arg;
    const double* y = j->y;
    double* out = j->out;
    int n = j->n, d = j->d;
    double eps2 = j->eps2;
    for (int i = j->i0; i < j->i1; i++) {
        const double* yi = y + (long)i*d;
        double* outi = out + (long)i*n;
        for (int jj = 0; jj <= i; jj++) {
            const double* yj = y + (long)jj*d;
            double s = 0.0;
            for (int k = 0; k < d; k++) {
                double diff = yi[k] - yj[k];
                s += diff*diff;
            }
            double r2 = s * eps2;
            double v = 0.0;
            if (r2 > 0.0) {
                v = r2 * log(sqrt(r2));
            }
            outi[jj] = v;
        }
    }
    return NULL;
}

void build(const double* y, int n, int d, double eps, double* out, int nthreads) {
    pthread_t th[16];
    Job jobs[16];
    /* split rows so each thread gets equal triangular work: i^2 proportional */
    int bounds[17];
    bounds[0] = 0;
    for (int t = 1; t <= nthreads; t++) {
        double frac = (double)t / nthreads;
        bounds[t] = (int)(n * sqrt(frac));
    }
    bounds[nthreads] = n;
    for (int t = 0; t < nthreads; t++) {
        jobs[t].y = y; jobs[t].out = out; jobs[t].n = n; jobs[t].d = d;
        jobs[t].i0 = bounds[t]; jobs[t].i1 = bounds[t+1];
        jobs[t].eps2 = eps*eps;
        pthread_create(&th[t], NULL, worker, &jobs[t]);
    }
    for (int t = 0; t < nthreads; t++) pthread_join(th[t], NULL);
    /* mirror */
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) out[(long)i*n + j] = out[(long)j*n + i];
    }
}

int main() {
    int n = 3000, d = 4;
    double* y = malloc(sizeof(double)*(long)n*d);
    double* out = malloc(sizeof(double)*(long)n*n);
    srand(0);
    for (long i = 0; i < (long)n*d; i++) y[i] = rand()/(double)RAND_MAX;
    for (int nt = 1; nt <= 6; nt++) {
        double t0 = now();
        build(y, n, d, 1.0, out, nt);
        double t1 = now();
        printf("threads %d build %.3f checksum %g\n", nt, t1-t0, out[(long)n*n/2]);
    }
    /* dgesv */
    int nn = 2500;
    double* A = malloc(sizeof(double)*(long)nn*nn);
    double* B = malloc(sizeof(double)*nn);
    for (long i = 0; i < (long)nn*nn; i++) A[i] = (i < (long)n*n) ? out[i] : 0.1;
    for (int i = 0; i < nn; i++) { B[i] = 1.0; A[(long)i*nn + i] += nn; }
    __CLPK_integer N = nn, NRHS = 1, LDA = nn, LDB = nn, INFO;
    __CLPK_integer* IPIV = malloc(sizeof(__CLPK_integer)*nn);
    double t0 = now();
    dgesv_(&N, &NRHS, A, &LDA, IPIV, B, &LDB, &INFO);
    double t1 = now();
    printf("dgesv %d %.3f info %d\n", nn, t1-t0, (int)INFO);
    return 0;
}
