/* Right-looking blocked LU with partial pivoting, row-major.
   Uses cblas for trailing update. */
int lu_blocked(double* A, int n, int* piv, int BS) {
    for (int i = 0; i < n; i++) piv[i] = i;
    double* col = malloc(sizeof(double)*n);
    for (int k = 0; k < n; k += BS) {
        int kb = (k + BS <= n) ? BS : n - k;
        /* factor panel A[k:n, k:k+kb] with partial pivoting, applying pivots to whole row */
        for (int j = 0; j < kb; j++) {
            int colj = k + j;
            /* find pivot in A[colj:n, colj] */
            int pivrow = colj;
            double maxv = fabs(A[(long)colj*n + colj]);
            for (int i = colj+1; i < n; i++) {
                double v = fabs(A[(long)i*n + colj]);
                if (v > maxv) { maxv = v; pivrow = i; }
            }
            if (maxv == 0.0) { free(col); return colj+1; }
            if (pivrow != colj) {
                /* swap rows */
                double* r1 = A + (long)colj*n;
                double* r2 = A + (long)pivrow*n;
                for (int c = 0; c < n; c++) { double tmp = r1[c]; r1[c] = r2[c]; r2[c] = tmp; }
                int tp = piv[colj]; piv[colj] = piv[pivrow]; piv[pivrow] = tp;
            }
            double diag = A[(long)colj*n + colj];
            double inv = 1.0 / diag;
            for (int i = colj+1; i < n; i++) A[(long)i*n + colj] *= inv;
            /* update panel columns to the right within panel */
            for (int c = colj+1; c < k+kb; c++) {
                double a = A[(long)colj*n + c];
                for (int i = colj+1; i < n; i++) {
                    A[(long)i*n + c] -= A[(long)i*n + colj] * a;
                }
            }
        }
        int kend = k + kb;
        if (kend >= n) break;
        int m = n - kend;       /* trailing rows */
        int nb = n - kend;      /* trailing cols */
        /* trailing update: A[kend:n, kend:n] -= A[kend:n, k:kend] * A[k:kend, kend:n]
           L is (m x kb) at A[kend, k], U is (kb x nb) at A[k, kend]
           row-major: use cblas_dgemm
           C = L(m x kb) * U(kb x nb)
           L row-major with leading dim n, starting at A[kend*n + k]
           U row-major with leading dim n, starting at A[k*n + kend]
        */
        cblas_dgemm(CblasRowMajor, CblasNoTrans, CblasNoTrans,
                    m, nb, kb,
                    -1.0,
                    A + (long)kend*n + k, n,
                    A + (long)k*n + kend, n,
                    1.0,
                    A + (long)kend*n + kend, n);
    }
    free(col);
    return 0;
}

void solve_lu(const double* LU, const int* piv, int n, double* b) {
    /* apply pivots */
    double* bp = malloc(sizeof(double)*n);
    for (int i = 0; i < n; i++) bp[i] = b[piv[i]];
    /* forward */
    for (int i = 0; i < n; i++) {
        double s = bp[i];
        const double* row = LU + (long)i*n;
        for (int j = 0; j < i; j++) s -= row[j]*bp[j];
        bp[i] = s;
    }
    /* back */
    for (int i = n-1; i >= 0; i--) {
        double s = bp[i];
        const double* row = LU + (long)i*n;
        for (int j = i+1; j < n; j++) s -= row[j]*bp[j];
        bp[i] = s / row[i];
    }
    memcpy(b, bp, sizeof(double)*n);
    free(bp);
}

int main() {
    int n = 2000;
    double* A = malloc(sizeof(double)*(long)n*n);
    double* Ac = malloc(sizeof(double)*(long)n*n);
    double* b = malloc(sizeof(double)*n);
    double* b0 = malloc(sizeof(double)*n);
    srand(1);
    for (long i = 0; i < (long)n*n; i++) A[i] = (rand()/(double)RAND_MAX) - 0.5;
    for (int i = 0; i < n; i++) { A[(long)i*n + i] += n; b[i] = rand()/(double)RAND_MAX; }
    memcpy(Ac, A, sizeof(double)*(long)n*n);
    memcpy(b0, b, sizeof(double)*n);
    int* piv = malloc(sizeof(int)*n);

    for (int BS = 32; BS <= 256; BS *= 2) {
        memcpy(Ac, A, sizeof(double)*(long)n*n);
        memcpy(b, b0, sizeof(double)*n);
        double t0 = now();
        int info = lu_blocked(Ac, n, piv, BS);
        double t1 = now();
        solve_lu(Ac, piv, n, b);
        /* residual */
        double res = 0, nb = 0;
        for (int i = 0; i < n; i++) {
            double s = 0;
            for (int j = 0; j < n; j++) s += A[(long)i*n + j]*b[j];
            res += (s - b0[i])*(s - b0[i]);
            nb += b0[i]*b0[i];
        }
        printf("BS %d time %.3f info %d relres %.3e\n", BS, t1-now()+ (now()-t0), info, sqrt(res/nb));
        /* fix timing print */
        printf("   elapsed %.3f\n", t1 - t0);
    }

    /* dgesv reference: column major */
    double* AF = malloc(sizeof(double)*(long)n*n);
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) AF[(long)j*n + i] = A[(long)i*n + j];
    memcpy(b, b0, sizeof(double)*n);
    __CLPK_integer N = n, NRHS = 1, LDA = n, LDB = n, INFO;
    __CLPK_integer* IPIV = malloc(sizeof(__CLPK_integer)*n);
    double t0 = now();
    dgesv_(&N, &NRHS, AF, &LDA, IPIV, b, &LDB, &INFO);
    double t1 = now();
    printf("dgesv %.3f info %d\n", t1-t0, (int)INFO);
    return 0;
}
