*/

int lu_left(double* A, int n, int* ipiv, int BS) {
    /* A column-major */
    for (int i = 0; i < n; i++) ipiv[i] = i+1; /* 1-based like lapack, we'll track separately */
    int* ipiv_local = malloc(sizeof(int)*n);
    for (int k = 0; k < n; k += BS) {
        int kb = (k + BS <= n) ? BS : n - k;
        /* Apply previous pivots to current panel A[k:n, k:k+kb]? 
           For left-looking we need to apply all prior transformations.
           This is getting messy. Use LAPACK dgetrf directly on panel after
           applying prior L and pivots.
        */
        /* Apply prior row swaps to the panel columns */
        for (int j = 0; j < kb; j++) {
            double* col = A + (long)(k+j)*n;
            for (int i = 0; i < k; i++) {
                int p = ipiv_local[i];
                if (p != i) {
                    double tmp = col[i]; col[i] = col[p]; col[p] = tmp;
                }
            }
        }
        /* Apply prior L: panel_top = L^{-1} panel_top, i.e. triangular solve
           L[0:k,0:k] * X = A[0:k, k:k+kb]  (unit lower)
           dtrsm
        */
        if (k > 0) {
            cblas_dtrsm(CblasColMajor, CblasLeft, CblasLower, CblasNoTrans, CblasUnit,
                        k, kb, 1.0, A, n, A + k*n, n);
            /* trailing panel update: A[k:n, k:k+kb] -= A[k:n, 0:k] * A[0:k, k:k+kb] */
            cblas_dgemm(CblasColMajor, CblasNoTrans, CblasNoTrans,
                        n - k, kb, k,
                        -1.0, A + k, n, A + (long)k*n, n,
                        1.0, A + (long)k*n + k, n);
        }
        /* factor panel A[k:n, k:k+kb] with unblocked LU + partial pivoting */
        for (int j = 0; j < kb; j++) {
            int colj = k + j;
            double* col = A + (long)colj*n;
            int piv = colj;
            double maxv = fabs(col[colj]);
            for (int i = colj+1; i < n; i++) {
                double v = fabs(col[i]);
                if (v > maxv) { maxv = v; piv = i; }
            }
            ipiv_local[colj] = piv;
            if (maxv == 0.0) { free(ipiv_local); return colj+1; }
            if (piv != colj) {
                /* swap rows across ALL columns computed so far (0..colj) and panel rest */
                cblas_dswap(colj+1, A + colj, n, A + piv, n);
                /* also swap within remaining panel columns? those not yet swapped for this pivot.
                   Remaining panel columns j+1..kb-1 have had prior pivots applied but not this one.
                   We should swap them too so subsequent columns see the pivot.
                */
                for (int c = colj+1; c < k+kb; c++) {
                    double* cc = A + (long)c*n;
                    double tmp = cc[colj]; cc[colj] = cc[piv]; cc[piv] = tmp;
                }
            }
            double inv = 1.0 / col[colj];
            for (int i = colj+1; i < n; i++) col[i] *= inv;
            /* rank-1 update of remaining panel */
            if (colj+1 < k+kb) {
                cblas_dger(CblasColMajor, n - colj - 1, k+kb - colj - 1,
                           -1.0, col + colj + 1, 1,
                           A + (long)(colj+1)*n + colj, n,
                           A + (long)(colj+1)*n + colj + 1, n);
            }
        }
    }
    memcpy(ipiv, ipiv_local, sizeof(int)*n);
    free(ipiv_local);
    return 0;
}

int main() {
    int n = 2000;
    double* A = malloc(sizeof(double)*(long)n*n);
    double* Ac = malloc(sizeof(double)*(long)n*n);
    srand(1);
    for (long i = 0; i < (long)n*n; i++) A[i] = (rand()/(double)RAND_MAX) - 0.5;
    for (int i = 0; i < n; i++) A[(long)i*n + i] += n;

    int* ipiv = malloc(sizeof(int)*n);
    for (int BS = 16; BS <= 128; BS *= 2) {
        memcpy(Ac, A, sizeof(double)*(long)n*n);
        double t0 = now();
        int info = lu_left(Ac, n, ipiv, BS);
        double t1 = now();
        printf("BS %d time %.3f info %d\n", BS, t1-t0, info);
    }
    memcpy(Ac, A, sizeof(double)*(long)n*n);
    __CLPK_integer N = n, LDA = n, INFO;
    __CLPK_integer* IPIV = malloc(sizeof(__CLPK_integer)*n);
    double t0 = now();
    dgetrf_(&N, &N, Ac, &LDA, IPIV, &INFO);
    double t1 = now();
    printf("dgetrf %.3f info %d\n", t1-t0, (int)INFO);
    return 0;
}
