#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <Accelerate/Accelerate.h>
#include <mach/mach_time.h>

static double now() {
    static mach_timebase_info_data_t info;
    if (info.denom == 0) mach_timebase_info(&info);
    return (double)mach_absolute_time() * info.numer / info.denom / 1e9;
}

typedef struct {
    const float* y; float* out;
    int n, d, i0, i1; float eps2; int kernel; /* 0 tps, 1 gaussian, 2 cubic, 3 mq, 4 linear, 5 quintic */
} Job;

void* worker(void* arg) {
    Job* j = arg;
    int n = j->n, d = j->d, kernel = j->kernel;
    float eps2 = j->eps2;
    for (int i = j->i0; i < j->i1; i++) {
        const float* yi = j->y + (long)i*d;
        float* outi = j->out + (long)i*n;
        for (int jj = 0; jj <= i; jj++) {
            const float* yj = j->y + (long)jj*d;
            float s = 0.f;
            for (int k = 0; k < d; k++) {
                float diff = yi[k] - yj[k];
                s += diff*diff;
            }
            float r2 = s * eps2;
            float v = 0.f;
            if (kernel == 1) { /* gaussian */
                v = expf(-r2);
            } else if (r2 > 0.f) {
                float r = sqrtf(r2);
                if (kernel == 0) v = r2 * logf(r);          /* tps */
                else if (kernel == 2) v = r2 * r;            /* cubic */
                else if (kernel == 3) v = -sqrtf(r2 + 1.f);  /* mq */
                else if (kernel == 4) v = -r;                /* linear */
                else if (kernel == 5) v = -(r2 * r2 * r);    /* quintic */
            } else {
                if (kernel == 3) v = -1.f;
            }
            outi[jj] = v;
        }
    }
    return NULL;
}

void build(const float* y, int n, int d, float eps, float* out, int kernel, int nthreads) {
    pthread_t th[8];
    Job jobs[8];
    int bounds[9];
    bounds[0] = 0;
    for (int t = 1; t <= nthreads; t++) bounds[t] = (int)(n * sqrt((double)t / nthreads));
    bounds[nthreads] = n;
    for (int t = 0; t < nthreads; t++) {
        jobs[t] = (Job){y, out, n, d, bounds[t], bounds[t+1], eps*eps, kernel};
        pthread_create(&th[t], NULL, worker, &jobs[t]);
    }
    for (int t = 0; t < nthreads; t++) pthread_join(th[t], NULL);
    for (int i = 0; i < n; i++)
        for (int j = i+1; j < n; j++) out[(long)i*n + j] = out[(long)j*n + i];
}

int main() {
    int ns[] = {2000, 3000, 5000};
    for (int ii = 0; ii < 3; ii++) {
        int n = ns[ii], d = 4;
        float* y = malloc(sizeof(float)*(long)n*d);
        float* out = malloc(sizeof(float)*(long)n*n);
        srand(0);
        for (long i = 0; i < (long)n*d; i++) y[i] = rand()/(float)RAND_MAX;
        double t0 = now();
        build(y, n, d, 1.f, out, 0, 6);
        double tb = now()-t0;
        /* sgesv */
        __CLPK_integer N = n, NRHS = 1, LDA = n, LDB = n, INFO;
        __CLPK_integer* IPIV = malloc(sizeof(__CLPK_integer)*n);
        float* B = malloc(sizeof(float)*n);
        for (int i = 0; i < n; i++) { B[i] = 1.f; out[(long)i*n + i] += 1.f; }
        /* transpose to column major */
        float* AF = malloc(sizeof(float)*(long)n*n);
        t0 = now();
        for (int c = 0; c < n; c++)
            for (int r = 0; r < n; r++) AF[(long)c*n + r] = out[(long)r*n + c];
        double tc = now()-t0;
        t0 = now();
        sgesv_(&N, &NRHS, AF, &LDA, IPIV, B, &LDB, &INFO);
        double ts = now()-t0;
        printf("n=%d build=%.3f transpose=%.3f sgesv=%.3f total=%.3f info=%d\n", n, tb, tc, ts, tb+tc+ts, (int)INFO);
        free(y); free(out); free(AF); free(B); free(IPIV);
    }
    return 0;
}
