import time
import numpy as np
from scipy.interpolate import RBFInterpolator
from scipy.interpolate._rbfinterp_common import _monomial_powers_impl
from scipy.linalg.lapack import sgesv, dgesv
from reference import Task

def powers_of(ndim, degree):
    out = np.asarray(_monomial_powers_impl(ndim, degree), dtype=np.int64)
    if out.size == 0:
        return out.reshape(0, ndim)
    return out

def poly(xhat, powers):
    n, d = xhat.shape
    r = powers.shape[0]
    if r == 0:
        return np.zeros((n, 0), dtype=xhat.dtype)
    out = np.ones((n, r), dtype=np.float64)
    for k in range(d):
        p = powers[:, k]
        if np.any(p):
            out *= np.power(xhat[:, k:k+1], p[None, :])
    return out

DEGREE = {'multiquadric':0,'linear':0,'thin_plate_spline':1,'cubic':1,'quintic':2,
          'gaussian':0,'inverse_multiquadric':0,'inverse_quadratic':0}

def rbf_solve(x, y, xt, kernel, eps, smoothing, dtype=np.float64):
    x = np.ascontiguousarray(x, np.float64)
    xt = np.ascontiguousarray(xt, np.float64)
    y = np.ascontiguousarray(y, np.float64).ravel()
    n, d = x.shape
    degree = DEGREE[kernel]
    pw = powers_of(d, degree)
    r = pw.shape[0]
    mins = x.min(0); maxs = x.max(0)
    shift = (maxs+mins)/2
    scale = (maxs-mins)/2
    scale[scale==0] = 1.0
    ye = x * eps
    sq = np.sum(ye*ye, axis=1)
    r2 = sq[:,None] + sq[None,:] - 2*(ye @ ye.T)
    np.maximum(r2, 0, out=r2)
    K = apply_kernel(r2, kernel)
    xhat = (x - shift)/scale
    P = poly(xhat, pw)
    N = n + r
    if dtype == np.float32:
        A = np.zeros((N, N), dtype=np.float32, order='F')
        A[:n,:n] = K.astype(np.float32)
        if r:
            A[:n, n:] = P.astype(np.float32)
            A[n:, :n] = P.T.astype(np.float32)
        for i in range(n):
            A[i,i] += np.float32(smoothing)
        rhs = np.zeros((N,1), dtype=np.float32, order='F')
        rhs[:n,0] = y.astype(np.float32)
        _,_,c,info = sgesv(A, rhs, overwrite_a=1, overwrite_b=1)
    else:
        A = np.zeros((N, N), dtype=np.float64, order='F')
        A[:n,:n] = K
        if r:
            A[:n, n:] = P
            A[n:, :n] = P.T
        for i in range(n):
            A[i,i] += smoothing
        rhs = np.zeros((N,1), dtype=np.float64, order='F')
        rhs[:n,0] = y
        _,_,c,info = dgesv(A, rhs, overwrite_a=1, overwrite_b=1)
    c = np.asarray(c, np.float64).ravel()
    te = xt * eps
    sqt = np.sum(te*te, axis=1)
    r2t = sqt[:,None] + sq[None,:] - 2*(te @ ye.T)
    np.maximum(r2t, 0, out=r2t)
    Kt = apply_kernel(r2t, kernel)
    pred = Kt @ c[:n]
    if r:
        xthat = (xt - shift)/scale
        pred += poly(xthat, pw) @ c[n:]
    return pred, info

def apply_kernel(r2, kernel):
    if kernel == 'gaussian':
        return np.exp(-r2)
    if kernel == 'inverse_multiquadric':
        return 1.0/np.sqrt(r2+1.0)
    if kernel == 'inverse_quadratic':
        return 1.0/(r2+1.0)
    if kernel == 'multiquadric':
        return -np.sqrt(r2+1.0)
    if kernel == 'linear':
        return -np.sqrt(r2)
    if kernel == 'cubic':
        return r2*np.sqrt(r2)
    if kernel == 'quintic':
        return -(r2*r2*np.sqrt(r2))
    if kernel == 'thin_plate_spline':
        rr = np.sqrt(r2)
        with np.errstate(divide='ignore', invalid='ignore'):
            K = np.where(r2==0, 0.0, r2*np.log(rr))
        return K
    raise ValueError(kernel)

task = Task()
for seed in list(range(20)) + [37, 38]:
    p = task.generate_problem(n=150, random_seed=seed)
    cfg = p['rbf_config']
    x = np.asarray(p['x_train'], float)
    yv = np.asarray(p['y_train'], float).ravel()
    xt = np.asarray(p['x_test'], float)
    if len(x) > 2500:
        continue
    t0 = time.perf_counter()
    ref = RBFInterpolator(x, yv, kernel=cfg['kernel'], epsilon=cfg['epsilon'], smoothing=cfg['smoothing'])(xt)
    tref = time.perf_counter()-t0
    t0 = time.perf_counter()
    pred, info = rbf_solve(x, yv, xt, cfg['kernel'], cfg['epsilon'], cfg['smoothing'], dtype=np.float32)
    dt = time.perf_counter()-t0
    rngv = max(np.ptp(ref), 1e-10)
    err = np.sqrt(np.mean((pred-ref)**2))/rngv
    print(f"seed {seed:2d} n={len(x):5d} d={x.shape[1]} {cfg['kernel'][:14]:14s} ref={tref:.3f} f32={dt:.3f} spd={tref/max(dt,1e-9):.2f} info={info} nrmse={err:.3e} {'OK' if err<0.05 else 'BAD'}")
PY"}

{"command":"cat > rbf_kernels.c << 'EOF'
/* Fast RBF kernel matrix and cross-kernel evaluation.
   Column-major output so LAPACK sgesv/dgesv can use it directly.
   Build with:
     clang -O3 -ffast-math -march=native -shared -fPIC -o rbf_kernels.so rbf_kernels.c -lpthread
*/
#include <math.h>
#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>

enum { K_LINEAR=0, K_TPS=1, K_CUBIC=2, K_QUINTIC=3, K_MQ=4, K_IMQ=5, K_IQ=6, K_GAUSS=7 };

static inline float kf(float r2, int kernel) {
    switch (kernel) {
    case K_GAUSS: return expf(-r2);
    case K_IMQ:   return 1.f / sqrtf(r2 + 1.f);
    case K_IQ:    return 1.f / (r2 + 1.f);
    case K_MQ:    return -sqrtf(r2 + 1.f);
    case K_LINEAR: return -sqrtf(r2);
    case K_CUBIC: {
        float r = sqrtf(r2);
        return r2 * r;
    }
    case K_QUINTIC: {
        float r = sqrtf(r2);
        return -(r2 * r2 * r);
    }
    case K_TPS: {
        if (r2 == 0.f) return 0.f;
        float r = sqrtf(r2);
        return r2 * logf(r);
    }
    default: return 0.f;
    }
}

static inline double kfd(double r2, int kernel) {
    switch (kernel) {
    case K_GAUSS: return exp(-r2);
    case K_IMQ:   return 1.0 / sqrt(r2 + 1.0);
    case K_IQ:    return 1.0 / (r2 + 1.0);
    case K_MQ:    return -sqrt(r2 + 1.0);
    case K_LINEAR: return -sqrt(r2);
    case K_CUBIC: {
        double r = sqrt(r2);
        return r2 * r;
    }
    case K_QUINTIC: {
        double r = sqrt(r2);
        return -(r2 * r2 * r);
    }
    case K_TPS: {
        if (r2 == 0.0) return 0.0;
        double r = sqrt(r2);
        return r2 * log(r);
    }
    default: return 0.0;
    }
}

typedef struct {
    const float* y;   /* (n, d) row-major, already scaled by epsilon */
    float* out;       /* (n, n) column-major */
    int n, d, i0, i1, kernel;
} JobF;

static void* worker_f(void* arg) {
    JobF* j = (JobF*)arg;
    int n = j->n, d = j->d, kernel = j->kernel;
    const float* y = j->y;
    float* out = j->out;
    for (int i = j->i0; i < j->i1; i++) {
        const float* yi = y + (long)i * d;
        for (int jj = 0; jj <= i; jj++) {
            const float* yj = y + (long)jj * d;
            float s = 0.f;
            for (int k = 0; k < d; k++) {
                float diff = yi[k] - yj[k];
                s += diff * diff;
            }
            float v = kf(s, kernel);
            out[(long)jj * n + i] = v;
            out[(long)i * n + jj] = v;
        }
    }
    return NULL;
}

typedef struct {
    const double* y;
    double* out;
    int n, d, i0, i1, kernel;
} JobD;

static void* worker_d(void* arg) {
    JobD* j = (JobD*)arg;
    int n = j->n, d = j->d, kernel = j->kernel;
    const double* y = j->y;
    double* out = j->out;
    for (int i = j->i0; i < j->i1; i++) {
        const double* yi = y + (long)i * d;
        for (int jj = 0; jj <= i; jj++) {
            const double* yj = y + (long)jj * d;
            double s = 0.0;
            for (int k = 0; k < d; k++) {
                double diff = yi[k] - yj[k];
                s += diff * diff;
            }
            double v = kfd(s, kernel);
            out[(long)jj * n + i] = v;
            out[(long)i * n + jj] = v;
        }
    }
    return NULL;
}

static int nthreads_default(void) {
    const char* e = getenv("RBF_THREADS");
    if (e && *e) {
        int v = atoi(e);
        if (v >= 1 && v <= 16) return v;
    }
    return 4;
}

/* out must be preallocated n*n column-major. y is (n, d) row-major, epsilon-scaled. */
void kernel_matrix_f32(const float* y, int n, int d, int kernel, float* out) {
    int nt = nthreads_default();
    if (n < 256) nt = 1;
    if (nt == 1) {
        JobF j = {y, out, n, d, 0, n, kernel};
        worker_f(&j);
        return;
    }
    pthread_t th[16];
    JobF jobs[16];
