#include <math.h>
#include <pthread.h>
#include <stdlib.h>

enum { K_LINEAR=0, K_TPS=1, K_CUBIC=2, K_QUINTIC=3, K_MQ=4, K_IMQ=5, K_IQ=6, K_GAUSS=7 };

static inline float kf(float r2, int kernel) {
    switch (kernel) {
    case K_GAUSS:  return expf(-r2);
    case K_IMQ:    return 1.f / sqrtf(r2 + 1.f);
    case K_IQ:     return 1.f / (r2 + 1.f);
    case K_MQ:     return -sqrtf(r2 + 1.f);
    case K_LINEAR: return -sqrtf(r2);
    case K_CUBIC:  { float r = sqrtf(r2); return r2 * r; }
    case K_QUINTIC:{ float r = sqrtf(r2); return -(r2 * r2 * r); }
    case K_TPS:    { if (r2 == 0.f) return 0.f; float r = sqrtf(r2); return r2 * logf(r); }
    default: return 0.f;
    }
}

static inline double kfd(double r2, int kernel) {
    switch (kernel) {
    case K_GAUSS:  return exp(-r2);
    case K_IMQ:    return 1.0 / sqrt(r2 + 1.0);
    case K_IQ:     return 1.0 / (r2 + 1.0);
    case K_MQ:     return -sqrt(r2 + 1.0);
    case K_LINEAR: return -sqrt(r2);
    case K_CUBIC:  { double r = sqrt(r2); return r2 * r; }
    case K_QUINTIC:{ double r = sqrt(r2); return -(r2 * r2 * r); }
    case K_TPS:    { if (r2 == 0.0) return 0.0; double r = sqrt(r2); return r2 * log(r); }
    default: return 0.0;
    }
}

typedef struct {
    const float* y; float* out;
    int n, d, lda, i0, i1, kernel;
} JobF;

static void* worker_f(void* arg) {
    JobF* j = (JobF*)arg;
    int n = j->n, d = j->d, lda = j->lda, kernel = j->kernel;
    const float* y = j->y;
    float* out = j->out;
    for (int i = j->i0; i < j->i1; i++) {
        const float* yi = y + (long)i * d;
        for (int col = 0; col <= i; col++) {
            const float* yj = y + (long)col * d;
            float s = 0.f;
            for (int k = 0; k < d; k++) {
                float diff = yi[k] - yj[k];
                s += diff * diff;
            }
            float v = kf(s, kernel);
            out[(long)col * lda + i] = v;
            out[(long)i * lda + col] = v;
        }
    }
    return NULL;
