import ctypes
import os
import subprocess
import tempfile

_DIR = os.path.dirname(os.path.abspath(__file__))
_SO = os.path.join(_DIR, "libbsgs.so")

_C_SOURCE = r"""
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static uint64_t barrett_mu, barrett_p;

static inline void barrett_init(uint64_t p) {
    if (p == barrett_p) return;
    barrett_p = p;
    /* a*b < 2^82 for p < 2^41; mu = floor(2^84 / p) gives quotient within 2. */
    barrett_mu = (uint64_t)(((__uint128_t)1 << 84) / p);
}

static inline uint64_t mulmod(uint64_t a, uint64_t b) {
    __uint128_t prod = (__uint128_t)a * b;
    __uint128_t q = (prod * barrett_mu) >> 84;
    uint64_t r = (uint64_t)(prod - q * barrett_p);
    if (r >= barrett_p) r -= barrett_p;
    if (r >= barrett_p) r -= barrett_p;
    return r;
}

static inline uint64_t modpow(uint64_t base, uint64_t exp) {
    uint64_t res = 1;
    while (exp) {
        if (exp & 1) res = mulmod(res, base);
        base = mulmod(base, base);
        exp >>= 1;
    }
    return res;
}

static uint64_t *keys = NULL;
static uint32_t *vals = NULL;
static uint64_t cap_alloc = 0;
static uint32_t *used = NULL;
static uint64_t used_cap = 0;

/* Discrete log of h base g modulo p, where g has order `order`. -1 if not found. */
int64_t bsgs(uint64_t g, uint64_t h, uint64_t p, uint64_t order) {
    if (order <= 1) return (h % p == 1) ? 0 : -1;
    barrett_init(p);

    uint64_t m = 1;
    while (m * m < order) m++;

    uint64_t cap = 1;
    while (cap < (m << 1)) cap <<= 1;
    if (cap > cap_alloc) {
        keys = (uint64_t *)realloc(keys, cap * sizeof(uint64_t));
        vals = (uint32_t *)realloc(vals, cap * sizeof(uint32_t));
        memset(keys, 0xFF, cap * sizeof(uint64_t));
        cap_alloc = cap;
    }
    uint64_t mask = cap - 1;
    if (m > used_cap) {
        used = (uint32_t *)realloc(used, m * sizeof(uint32_t));
        used_cap = m;
    }

    g %= p;
    uint32_t nused = 0;
    uint64_t e = 1;
    for (uint64_t j = 0; j < m; j++) {
        uint64_t slot = (e * 0x9E3779B97F4A7C15ULL) & mask;
        while (keys[slot] != UINT64_MAX) slot = (slot + 1) & mask;
        keys[slot] = e;
        vals[slot] = (uint32_t)j;
        used[nused++] = (uint32_t)slot;
        e = mulmod(e, g);
    }

    uint64_t factor = modpow(g, order - (m % order));
    uint64_t gamma = h % p;
    int64_t result = -1;
    for (uint64_t i = 0; i <= m; i++) {
        uint64_t slot = (gamma * 0x9E3779B97F4A7C15ULL) & mask;
        while (keys[slot] != UINT64_MAX && keys[slot] != gamma) slot = (slot + 1) & mask;
        if (keys[slot] == gamma) {
            result = (int64_t)((i * m + vals[slot]) % order);
            break;
        }
        gamma = mulmod(gamma, factor);
    }
    for (uint32_t i = 0; i < nused; i++) keys[used[i]] = UINT64_MAX;
    return result;
}
"""


def _load_lib():
    if not os.path.exists(_SO):
        src = os.path.join(_DIR, "bsgs.c")
        with open(src, "w") as f:
            f.write(_C_SOURCE)
        subprocess.check_call(["cc", "-O3", "-shared", "-fPIC", "-o", _SO, src])
    lib = ctypes.CDLL(_SO)
    lib.bsgs.argtypes = [ctypes.c_uint64, ctypes.c_uint64, ctypes.c_uint64, ctypes.c_uint64]
    lib.bsgs.restype = ctypes.c_int64
    return lib


_lib = _load_lib()


def _build_primes(limit=1 << 20):
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            start = i * i
            sieve[start::i] = b"\x00" * ((limit - start) // i + 1)
    return [i for i in range(2, limit + 1) if sieve[i]]


_SMALL_PRIMES = _build_primes()


def _factor(n):
    """Prime factorization of n by trial division. For 40-bit n the cofactor
    left after dividing out primes up to 2^20 is necessarily prime."""
    factors = []
    for q in _SMALL_PRIMES:
        if q * q > n:
            break
        if n % q == 0:
            c = 0
            while n % q == 0:
                n //= q
                c += 1
            factors.append((q, c))
    if n > 1:
        factors.append((n, 1))
    return factors


def _crt(rems, mods):
    M = 1
    for m in mods:
        M *= m
    x = 0
    for r, m in zip(rems, mods):
        Mi = M // m
        x = (x + r * Mi * pow(Mi, -1, m)) % M
    return x


def _dlog(g, h, p):
    h %= p
    g %= p
    if h == 1:
        return 0
    factors = _factor(p - 1)

    # order of g divides p - 1
    order = p - 1
    for q, e in factors:
        for _ in range(e):
            if pow(g, order // q, p) == 1:
                order //= q
            else:
                break

    ofac = []
    temp = order
    for q, _ in factors:
        c = 0
        while temp % q == 0:
            temp //= q
            c += 1
        if c:
            ofac.append((q, c))
    if temp > 1:
        ofac.append((temp, 1))

    # Pohlig-Hellman: solve the DLP modulo each prime-power factor, then CRT
    rems = []
    mods = []
    for q, e in ofac:
        qe = q ** e
        gq = pow(g, order // q, p)  # generator of the order-q subgroup
        xq = 0
        qpow = 1
        for _k in range(e):
            hk = pow(h * pow(g, -xq, p) % p, order // (qpow * q), p)
            if hk == 1:
                dk = 0
            else:
                dk = _lib.bsgs(gq, hk, p, q)
                if dk < 0:
                    raise ValueError("discrete log failed")
            xq += dk * qpow
            qpow *= q
        rems.append(xq % qe)
        mods.append(qe)
    return _crt(rems, mods)


class Solver:
    def solve(self, problem, **kwargs):
        return {"x": int(_dlog(int(problem["g"]), int(problem["h"]), int(problem["p"])))}

