#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* Open addressing hash map: key -> index, for baby-step giant-step.
   Keys are residues mod p (< 2^41), stored in uint64. Empty slot = UINT64_MAX. */

static inline uint64_t mulmod(uint64_t a, uint64_t b, uint64_t p) {
    return (uint64_t)(((__uint128_t)a * b) % p);
}

static inline uint64_t modpow(uint64_t base, uint64_t exp, uint64_t mod) {
    uint64_t res = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) res = mulmod(res, base, mod);
        base = mulmod(base, base, mod);
        exp >>= 1;
    }
    return res;
}

static inline uint64_t hash64(uint64_t x, uint64_t mask) {
    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27;
    x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x & mask;
}

/* returns discrete log of h base g mod p, order of g is `order`. -1 on failure. */
int64_t bsgs(uint64_t g, uint64_t h, uint64_t p, uint64_t order) {
    uint64_t m = 1;
    while (m * m < order) m++;

    uint64_t cap = 1;
    while (cap < 2 * m) cap <<= 1;
    uint64_t mask = cap - 1;

    uint64_t *keys = (uint64_t *)malloc(cap * sizeof(uint64_t));
    uint32_t *vals = (uint32_t *)malloc(cap * sizeof(uint32_t));
    if (!keys || !vals) { free(keys); free(vals); return -1; }
    memset(keys, 0xFF, cap * sizeof(uint64_t));

    uint64_t e = 1;
    for (uint64_t j = 0; j < m; j++) {
        uint64_t slot = hash64(e, mask);
        while (keys[slot] != UINT64_MAX && keys[slot] != e) slot = (slot + 1) & mask;
        if (keys[slot] == UINT64_MAX) { keys[slot] = e; vals[slot] = (uint32_t)j; }
        e = mulmod(e, g, p);
    }

    uint64_t factor = modpow(g, order - (m % order), p); /* g^{-m} = g^{order-m} */
    uint64_t gamma = h % p;
    int64_t result = -1;
    for (uint64_t i = 0; i < m; i++) {
        uint64_t slot = hash64(gamma, mask);
        while (keys[slot] != UINT64_MAX && keys[slot] != gamma) slot = (slot + 1) & mask;
        if (keys[slot] == gamma) {
            result = (int64_t)(i * m + vals[slot]);
            break;
        }
        gamma = mulmod(gamma, factor, p);
    }
    free(keys);
    free(vals);
    return result;
}
